PageHandlerAsyncWaiter::PageHandlerAsyncWaiter(
    PageHandler* proxy) : proxy_(proxy) {}

PageHandlerAsyncWaiter::~PageHandlerAsyncWaiter() = default;

void PageHandlerAsyncWaiter::GetChildFolders(
    const ::base::FilePath& path, std::vector<::base::FilePath>* out_paths) {
  base::RunLoop loop;
  proxy_->GetChildFolders(std::move(path),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<::base::FilePath>* out_paths
,
             const std::vector<::base::FilePath>& paths) {*out_paths = std::move(paths);
            loop->Quit();
          },
          &loop,
          out_paths));
  loop.Run();
}

std::vector<::base::FilePath> PageHandlerAsyncWaiter::GetChildFolders(
    const ::base::FilePath& path) {
  std::vector<::base::FilePath> async_wait_result;
  GetChildFolders(std::move(path),&async_wait_result);
  return async_wait_result;
}

void PageHandlerAsyncWaiter::GetSyncingPaths(
    PageHandler::GetSyncPathError* out_error, std::vector<::base::FilePath>* out_syncing_paths) {
  base::RunLoop loop;
  proxy_->GetSyncingPaths(
      base::BindOnce(
          [](base::RunLoop* loop,
             PageHandler::GetSyncPathError* out_error
,
             std::vector<::base::FilePath>* out_syncing_paths
,
             PageHandler::GetSyncPathError error,
             const std::vector<::base::FilePath>& syncing_paths) {*out_error = std::move(error);*out_syncing_paths = std::move(syncing_paths);
            loop->Quit();
          },
          &loop,
          out_error,
          out_syncing_paths));
  loop.Run();
}








